/* Quality sidecars are evidence supplied by the reviewer, scoped to exact membership. */
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.ReviewQuality=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){
 'use strict';const storageKey='spikeagent-quality-sidecars-v1';
 function csv(text){const rows=[];let row=[],value='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){value+='"';i++;}else quoted=!quoted;}else if(!quoted&&(c===','||c==='\t')){row.push(value);value='';}else if(!quoted&&(c==='\n'||c==='\r')){if(c==='\r'&&text[i+1]==='\n')i++;row.push(value);if(row.some(x=>x.trim()))rows.push(row);row=[];value='';}else value+=c;}if(quoted)throw Error('Unclosed CSV quote');row.push(value);if(row.some(x=>x.trim()))rows.push(row);if(!rows.length)throw Error('Empty table');const headers=rows.shift().map(x=>x.trim().replace(/^\uFEFF/,''));if(new Set(headers).size!==headers.length)throw Error('Duplicate column');return rows.map(r=>{if(r.length!==headers.length)throw Error('Table column count differs');return Object.fromEntries(headers.map((h,i)=>[h,r[i].trim()]));});}
 function scope(c){return [c.dataset_id,c.mat_sha256,c.state_sha256].join(':');}
 function validate(value,c){
  if(value.schema!=='spikeagent-quality-v1'||value.dataset_id!==c.dataset_id||value.source_sha256!==c.mat_sha256||value.state_sha256!==c.state_sha256)throw Error('Quality file belongs to another recording or grouping');
  if(!['higher','lower'].includes(value.direction)||typeof value.metric!=='string'||!value.metric.trim()||value.metric.length>100||typeof value.provenance!=='string'||!value.provenance.trim()||value.provenance.length>500||!Array.isArray(value.rows)||!value.rows.length||value.rows.length>10000)throw Error('Provide a metric, source, direction and cluster rows');
  const ids=new Set(c.units.map(u=>u.cluster_id)),seen=new Set(),rows=value.rows.map(r=>{const id=Number(r.cluster_id),score=r.score===''||r.score==null?null:Number(r.score);if(!Number.isInteger(id)||!ids.has(id)||seen.has(id)||score!==null&&!Number.isFinite(score)||r.label!=null&&(typeof r.label!=='string'||r.label.length>100))throw Error('Invalid, duplicate or unknown cluster score');seen.add(id);return {cluster_id:id,score,label:r.label||''};});
  return {...value,rows,metric:value.metric.trim(),provenance:value.provenance.trim()};
 }
 function load(c){try{const x=JSON.parse(localStorage.getItem(storageKey)||'{}')[scope(c)];return x?validate(x,c):null;}catch{return null;}}
 function save(value,c){const clean=validate(value,c),all=JSON.parse(localStorage.getItem(storageKey)||'{}');all[scope(c)]=clean;localStorage.setItem(storageKey,JSON.stringify(all));return clean;}
 function value(c,id){const file=load(c),row=file?.rows.find(r=>r.cluster_id===id);return {file,row,score:row?.score??null};}
 function rank(c,id){const q=value(c,id);return q.score==null?Infinity:q.file.direction==='higher'?-q.score:q.score;}
 function cell(c,id){const q=value(c,id);return q.row?(q.score==null?'—':String(q.score))+(q.row.label?' · '+q.row.label:''):'Not provided by input';}
 function controls(){return '<button type="button" class="button small" data-quality-import>Import quality scores</button>';}
 function bind(host,c){for(const button of host.querySelectorAll('[data-quality-import]'))button.onclick=()=>open(c);}
 function open(c){
  const old=load(c),dialog=document.createElement('dialog');dialog.className='quality-import-dialog';dialog.innerHTML='<div class="modal-heading"><h2>Quality scores</h2><button class="icon-button" aria-label="Close quality import">×</button></div><p>For this recording and grouping only. Imported scores keep their source; missing scores stay missing.</p><label>Metric name<input data-metric maxlength="100" placeholder="e.g. isolation distance"></label><label>Source<input data-provenance maxlength="500" placeholder="Sorter/export and version"></label><label>Better scores are<select data-direction><option value="higher">Higher</option><option value="lower">Lower</option></select></label><label>CSV, TSV or JSON<input data-file type="file" accept=".csv,.tsv,.json"></label><p class="field-help">CSV/TSV: cluster_id, score, label (optional).</p><div class="input-actions"><button class="button" data-template>Download JSON template</button><button class="button primary" data-import>Import</button><button class="button" data-clear>Remove imported scores</button></div><p role="status" data-status></p>';
  document.body.append(dialog);dialog.querySelector('.icon-button').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());const $=s=>dialog.querySelector(s);$('[data-metric]').value=old?.metric||'';$('[data-provenance]').value=old?.provenance||'';$('[data-direction]').value=old?.direction||'higher';
  const template=()=>({schema:'spikeagent-quality-v1',dataset_id:c.dataset_id,source_sha256:c.mat_sha256,state_sha256:c.state_sha256,metric:$('[data-metric]').value||'Metric name',provenance:$('[data-provenance]').value||'Sorter/export and version',direction:$('[data-direction]').value,rows:c.units.map(u=>({cluster_id:u.cluster_id,score:null,label:''}))});
  $('[data-template]').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(template(),null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=c.dataset_id+'.quality.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
  const refresh=()=>{if(typeof WorkingReview!=='undefined'&&WorkingReview.active)WorkingReview.render();else{renderQueue();renderEvidence();}};
  $('[data-import]').onclick=async()=>{try{const file=$('[data-file]').files[0];if(!file||file.size>2*1024*1024)throw Error('Choose a quality file up to 2 MiB');const text=await file.text();const data=file.name.toLowerCase().endsWith('.json')?JSON.parse(text):{...template(),metric:$('[data-metric]').value,provenance:$('[data-provenance]').value,rows:csv(text)};save(data,c);refresh();dialog.close();}catch(e){$('[data-status]').textContent=e.message;}};
  $('[data-clear]').onclick=()=>{try{const all=JSON.parse(localStorage.getItem(storageKey)||'{}');delete all[scope(c)];localStorage.setItem(storageKey,JSON.stringify(all));refresh();dialog.close();}catch(e){$('[data-status]').textContent=e.message;}};dialog.showModal();
 }
 return {csv,scope,validate,load,save,value,rank,cell,controls,bind,open};
});
